let state = null;

export function initialize(element, dotNetRef, timeoutMs) {
    const events = ["mousemove", "keydown", "click", "scroll"];
    let timerId = null;
    let isIdle = false;

    function resetTimer() {
        if (timerId !== null) {
            clearTimeout(timerId);
        }

        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnActiveCallback");
        }

        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnIdleCallback");
        }, timeoutMs);
    }

    events.forEach(evt => element.addEventListener(evt, resetTimer, { passive: true }));

    // Also listen on the document so global activity (e.g. tabbing, scrolling
    // outside the wrapper) is captured.
    events.forEach(evt => document.addEventListener(evt, resetTimer, { passive: true }));

    // Start the initial timer immediately.
    resetTimer();

    state = { element, events, resetTimer, timerId: () => timerId, clearTimer: () => clearTimeout(timerId) };
}

export function dispose() {
    if (!state) return;

    state.clearTimer();
    state.events.forEach(evt => state.element.removeEventListener(evt, state.resetTimer));
    state.events.forEach(evt => document.removeEventListener(evt, state.resetTimer));
    state = null;
}

